/* jitgen: turns the relocatable object assembled from src/runtime/jit/stencils.S into src/runtime/jit/stencils.h.
 *
 * Every `.text.<name>` section is one stencil. Its bytes are copied verbatim; every relocation against one of the
 * hole symbols H0..H5, HQ, JIT_T, JIT_X becomes a patch record (offset, which hole, kind, addend). The JIT only has to
 * memcpy a stencil and write the holes. Usage: jitgen stencils.o > stencils.h   (see `make jit-regen`) */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct { uint8_t ident[16]; uint16_t type, machine; uint32_t version; uint64_t entry, phoff, shoff; uint32_t flags;
                 uint16_t ehsize, phentsize, phnum, shentsize, shnum, shstrndx; } Ehdr;
typedef struct { uint32_t name, type; uint64_t flags, addr, offset, size; uint32_t link, info; uint64_t addralign, entsize; } Shdr;
typedef struct { uint32_t name; uint8_t info, other; uint16_t shndx; uint64_t value, size; } Sym;
typedef struct { uint64_t offset, info; int64_t addend; } Rela;

static unsigned char *img;
static size_t imglen;

static const char *hole_names[] = {"H0", "H1", "H2", "H3", "H4", "H5", "HQ", "JIT_T", "JIT_X", "HQ2"};

static int hole_id(const char *s) {
    for (int i = 0; i < 10; i++) if (strcmp(s, hole_names[i]) == 0) return i;
    fprintf(stderr, "jitgen: unknown symbol '%s'\n", s);
    exit(1);
}

int main(int argc, char **argv) {
    if (argc != 2) { fprintf(stderr, "usage: jitgen stencils.o > stencils.h\n"); return 2; }
    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror(argv[1]); return 1; }
    fseek(f, 0, SEEK_END);
    imglen = (size_t)ftell(f);
    fseek(f, 0, SEEK_SET);
    img = malloc(imglen);
    if (!img || fread(img, 1, imglen, f) != imglen) { fprintf(stderr, "jitgen: read failed\n"); return 1; }
    fclose(f);
    const Ehdr *eh = (const Ehdr *)(const void *)img;
    if (memcmp(eh->ident, "\177ELF", 4) != 0 || eh->ident[4] != 2 || eh->machine != 62) { fprintf(stderr, "jitgen: not an x86-64 ELF object\n"); return 1; }
    const Shdr *sh = (const Shdr *)(const void *)(img + eh->shoff);
    const char *shstr = (const char *)img + sh[eh->shstrndx].offset;

    /* pass 1: names */
    int ns = 0;
    static int sec_of[2048];
    for (int i = 0; i < eh->shnum; i++) {
        const char *n = shstr + sh[i].name;
        if (strncmp(n, ".text.", 6) == 0 && sh[i].type == 1) sec_of[ns++] = i;
    }
    printf("/* generated by tools/jitgen.c from stencils.S -- do not edit; run `make jit-regen` */\n");
    printf("enum {\n");
    for (int k = 0; k < ns; k++) printf("    ST_%s,\n", shstr + sh[sec_of[k]].name + 6);
    printf("    ST_COUNT\n};\n");
    printf("enum { HOLE_H0, HOLE_H1, HOLE_H2, HOLE_H3, HOLE_H4, HOLE_H5, HOLE_HQ, HOLE_T, HOLE_X, HOLE_HQ2 };\n");
    printf("enum { REL_ABS32, REL_ABS64, REL_PC32 };\n");
    printf("typedef struct { uint16_t at; uint8_t hole, kind; int32_t addend; } JReloc;\n");
    printf("typedef struct { uint32_t off, len, rel0, nrel; } JStencil;\n");

    /* bytes + relocs */
    size_t total = 0;
    int nrel_total = 0;
    printf("static const unsigned char jst_code[] = {");
    for (int k = 0; k < ns; k++) {
        const Shdr *s = &sh[sec_of[k]];
        for (uint64_t b = 0; b < s->size; b++) {
            if (total % 16 == 0) printf("\n    ");
            printf("0x%02x,", img[s->offset + b]);
            total++;
        }
    }
    printf("\n};\n");
    printf("static const JReloc jst_rel[] = {\n");
    static uint32_t off[2048], len[2048], rel0[2048], nrel[2048];
    size_t o = 0;
    for (int k = 0; k < ns; k++) {
        const Shdr *s = &sh[sec_of[k]];
        off[k] = (uint32_t)o;
        len[k] = (uint32_t)s->size;
        o += s->size;
        rel0[k] = (uint32_t)nrel_total;
        for (int j = 0; j < eh->shnum; j++) {
            if (sh[j].type != 4 || sh[j].info != (uint32_t)sec_of[k]) continue;
            const Sym *syms = (const Sym *)(const void *)(img + sh[sh[j].link].offset);
            const char *strs = (const char *)img + sh[sh[sh[j].link].link].offset;
            const Rela *r = (const Rela *)(const void *)(img + sh[j].offset);
            size_t nr = sh[j].size / sizeof(Rela);
            for (size_t q = 0; q < nr; q++) {
                uint32_t type = (uint32_t)(r[q].info & 0xffffffffu), sym = (uint32_t)(r[q].info >> 32);
                int hole = hole_id(strs + syms[sym].name);
                int kind;
                if (type == 10 || type == 11) kind = 0;        /* R_X86_64_32 / 32S */
                else if (type == 1) kind = 1;                  /* R_X86_64_64 */
                else if (type == 2 || type == 4) kind = 2;     /* PC32 / PLT32 */
                else { fprintf(stderr, "jitgen: unsupported relocation type %u\n", type); return 1; }
                printf("    {%u, HOLE_%s, %s, %d},\n", (unsigned)r[q].offset,
                       hole <= 5 ? hole_names[hole] : hole == 6 ? "HQ" : hole == 7 ? "T" : hole == 8 ? "X" : "HQ2",
                       kind == 0 ? "REL_ABS32" : kind == 1 ? "REL_ABS64" : "REL_PC32", (int)r[q].addend);
                nrel_total++;
                nrel[k]++;
            }
        }
    }
    printf("    {0, 0, 0, 0}\n};\n");
    printf("static const JStencil jst_tab[ST_COUNT] = {\n");
    for (int k = 0; k < ns; k++) printf("    {%u, %u, %u, %u}, /* %s */\n", off[k], len[k], rel0[k], nrel[k], shstr + sh[sec_of[k]].name + 6);
    printf("};\n");
    free(img);
    return 0;
}
